*{box-sizing:border-box} :root{--ink:#f4f3ef;--muted:#a5a9a9;--orange:#ff5428;--deep:#090d11;--panel:rgba(12,17,21,.91)}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#080b0f;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit;cursor:pointer}#game-shell{position:relative;width:100%;height:100%;min-height:500px;overflow:hidden;background:#0a1014}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(5,9,13,.86) 0%,rgba(5,9,13,.59) 31%,rgba(5,9,13,.07) 66%,rgba(5,9,13,.12) 100%),linear-gradient(0deg,rgba(3,6,9,.58),transparent 25%,transparent 72%,rgba(3,6,9,.45)}.topbar{position:absolute;z-index:5;left:0;right:0;top:0;height:88px;padding:0 6.4%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.11);transition:opacity .3s}.brand{border:0;background:none;display:flex;align-items:center;gap:12px;padding:0;text-align:left;font-family:'Barlow Condensed',sans-serif;font-size:23px;font-weight:800;letter-spacing:.04em;line-height:.83}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:2px solid var(--orange);color:var(--orange);font-size:23px;font-style:italic;transform:skew(-9deg)}.brand-hot{color:var(--orange)}.brand small{display:block;color:#9da3a5;font:600 8px 'DM Sans',sans-serif;letter-spacing:.31em;margin-top:8px}.top-center{font:700 10px 'DM Sans',sans-serif;letter-spacing:.2em;color:#e3e3df;display:flex;align-items:center;gap:10px}.live-dot{height:6px;width:6px;border-radius:50%;background:var(--orange);box-shadow:0 0 12px var(--orange)}.sound-button{border:1px solid rgba(255,255,255,.23);background:rgba(5,8,11,.3);padding:10px 14px;font-size:13px;color:var(--orange)}.sound-button span{font-size:9px;color:#dfe0df;letter-spacing:.13em;margin-left:6px}.screen{position:absolute;z-index:3;inset:0;padding:125px 6.4% 45px}.menu-copy{position:absolute;top:23%;left:10%;max-width:560px}.eyebrow{font-size:10px;letter-spacing:.22em;font-weight:700;color:#d0d2cf;margin:0 0 20px;display:flex;align-items:center;gap:11px}.eyebrow-line{width:26px;height:2px;background:var(--orange);display:inline-block}.menu-copy h1,.selection-heading h2,.pause-screen h2,.finish-screen h2{font-family:'Barlow Condensed',sans-serif;font-size:clamp(68px,8.5vw,120px);line-height:.78;letter-spacing:-.03em;font-weight:800;margin:0;text-shadow:0 5px 25px #000}.menu-copy h1>span:first-child,.selection-heading h2 span,.pause-screen h2 span,.finish-screen h2 span{color:var(--orange)}.period{color:var(--orange)}.intro{color:#c3c6c5;font-size:14px;line-height:1.75;margin:28px 0 26px}.primary-button{background:var(--orange);border:0;padding:16px 21px;min-width:216px;text-align:left;font-weight:800;font-size:10px;letter-spacing:.17em;box-shadow:0 8px 26px rgba(255,84,40,.18);transition:transform .18s,background .18s}.primary-button span{font-size:18px;float:right;line-height:10px}.primary-button:hover{background:#ff714a;transform:translateY(-2px)}.menu-stats{display:flex;align-items:center;gap:15px;margin-top:42px;font-size:8px;color:#c0c3c2;letter-spacing:.14em}.menu-stats b{font-size:14px;color:#fff;margin-right:5px}.menu-stats i{width:3px;height:3px;background:var(--orange);border-radius:50%}.menu-bottom{position:absolute;bottom:25px;left:6.4%;right:6.4%;display:flex;justify-content:space-between;font-size:8px;letter-spacing:.18em;color:#b1b5b4}.menu-bottom span:first-child{color:var(--orange)}.hidden{display:none!important}.selection-screen{padding:125px 6.4% 36px;background:linear-gradient(110deg,rgba(7,11,15,.95),rgba(7,11,15,.83) 54%,rgba(7,11,15,.51))}.selection-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:26px}.selection-heading .eyebrow{margin-bottom:13px}.selection-heading h2{font-size:clamp(48px,5.2vw,70px);line-height:.82}.heading-note{text-align:right;font-size:10px;line-height:1.8;letter-spacing:.16em;font-weight:700;padding-bottom:4px}.heading-note span{font-weight:400;letter-spacing:0;color:#9ba1a1}.location-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;max-height:calc(100% - 255px);overflow:auto;padding:2px 6px 6px 0;scrollbar-width:thin;scrollbar-color:#555 transparent}.location-card{height:86px;text-align:left;position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.17);padding:13px 15px;background:linear-gradient(115deg,rgba(28,37,42,.9),rgba(17,23,27,.91));transition:.2s}.location-card:before{content:'';position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.045));pointer-events:none}.location-card:hover,.location-card.selected{border-color:var(--orange);background:linear-gradient(115deg,rgba(83,38,28,.8),rgba(22,25,27,.95));transform:translateY(-2px)}.location-card .flag{font-size:18px;display:block;margin-bottom:7px}.location-card strong{font:700 17px 'Barlow Condensed',sans-serif;letter-spacing:.04em;display:block}.location-card small{font-size:8px;letter-spacing:.13em;color:#aab1b1}.location-card .card-index{position:absolute;right:12px;top:13px;color:#727a7c;font-size:8px;letter-spacing:.1em}.selection-footer{position:absolute;bottom:25px;left:6.4%;right:6.4%;height:43px;border-top:1px solid rgba(255,255,255,.15);display:flex;align-items:flex-end;justify-content:space-between}.selection-footer>span{font-size:8px;letter-spacing:.18em;color:#9fa5a5;padding-bottom:9px}.text-button{background:none;border:0;padding:10px 0;color:#d8d9d6;font-size:9px;font-weight:700;letter-spacing:.17em}.text-button:hover{color:var(--orange)}.car-screen{padding-top:120px}.car-screen .selection-heading{margin-bottom:19px}.car-groups{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:18px;height:calc(100% - 252px);overflow:auto;padding-right:6px}.car-group{min-width:0}.group-title{font:800 13px 'Barlow Condensed',sans-serif;letter-spacing:.15em;margin:0 0 8px;padding-bottom:7px;border-bottom:1px solid rgba(255,255,255,.23);display:flex;justify-content:space-between}.group-title span{font:500 9px 'DM Sans',sans-serif;color:#92999a;letter-spacing:.1em}.car-card{width:100%;height:54px;margin-bottom:5px;border:1px solid rgba(255,255,255,.12);background:rgba(23,30,34,.72);padding:0 11px;display:flex;align-items:center;gap:10px;text-align:left;transition:.18s}.car-card:hover,.car-card.selected{border-color:var(--orange);background:rgba(76,38,29,.7)}.car-swatch{display:block;width:31px;height:13px;border-radius:12px 12px 5px 5px;position:relative;flex:none;box-shadow:0 4px 8px #000}.car-swatch:before{content:'';position:absolute;left:9px;right:8px;top:-5px;height:8px;border-radius:8px 8px 1px 1px;background:inherit;filter:brightness(.7)}.car-card strong{font:600 13px 'Barlow Condensed',sans-serif;letter-spacing:.035em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1}.car-card small{font-size:8px;color:#929999;letter-spacing:.08em}.car-card.selected small{color:var(--orange)}.compact{min-width:190px;padding:13px 17px}.selection-footer .back-button{padding-bottom:8px}.pause-screen,.finish-screen{background:rgba(4,8,12,.82);padding-left:12%;display:flex;flex-direction:column;align-items:flex-start;justify-content:center}.pause-screen h2,.finish-screen h2{font-size:clamp(70px,9vw,112px);margin-bottom:27px}.pause-screen .eyebrow,.finish-screen .eyebrow{margin-bottom:19px}.pause-screen .text-button{margin-top:10px}.finish-screen{align-items:center;text-align:center;padding-left:6.4%}.finish-screen .eyebrow{justify-content:center}.finish-screen h2{margin-bottom:12px}.finish-screen>p:not(.eyebrow){color:#bbc0be;margin:5px 0 25px}.finish-actions{display:flex;flex-direction:column;align-items:center;gap:7px}.race-hud{position:absolute;z-index:4;inset:0;pointer-events:none}.race-hud button{pointer-events:auto}.hud-left{position:absolute;top:108px;left:5.5%;display:flex;align-items:stretch;gap:11px}.position-card,.lap-card{background:rgba(9,14,18,.75);border-left:2px solid var(--orange);padding:9px 13px;backdrop-filter:blur(7px)}.position-card strong{font:800 33px 'Barlow Condensed',sans-serif;color:var(--orange);display:inline-block}.position-card span,.position-card small{font:700 8px 'DM Sans',sans-serif;letter-spacing:.12em;color:#d4d7d4;margin-left:5px}.position-card small{display:block;margin:0;color:#899293}.lap-card>span{display:block;font-size:8px;letter-spacing:.15em;color:#b3b8b7}.lap-card strong{font:700 20px 'Barlow Condensed',sans-serif}.lap-card strong span{font:500 12px;color:#92999a}.lap-progress{width:90px;height:2px;background:#505656;margin-top:5px}.lap-progress i{height:100%;display:block;background:var(--orange);width:15%}.race-title{position:absolute;top:115px;left:50%;transform:translateX(-50%);text-align:center;text-shadow:0 2px 10px #000}.race-title span{font:800 16px 'Barlow Condensed',sans-serif;letter-spacing:.2em}.race-title small{display:block;font-size:7px;letter-spacing:.22em;color:#d2d4d1;margin-top:4px}.hud-right{position:absolute;top:106px;right:5.5%;display:flex;align-items:center;gap:17px}.speed-card{display:flex;align-items:baseline;gap:6px;text-shadow:0 2px 8px #000}.speed-card strong{font:800 38px 'Barlow Condensed',sans-serif}.speed-card span{font-size:8px;font-weight:700;letter-spacing:.13em;color:#ff6b45}.pause-button{border:1px solid rgba(255,255,255,.48);background:rgba(9,14,18,.58);width:36px;height:36px;font-weight:800}.nitro-wrap{position:absolute;right:5.5%;bottom:54px;width:155px;text-shadow:0 2px 8px #000}.nitro-wrap>span,.nitro-wrap small{display:block;font-size:8px;letter-spacing:.17em;font-weight:700}.nitro-wrap small{color:#aaa;font-size:7px;margin-top:5px}.nitro-track{height:4px;background:rgba(255,255,255,.28);margin-top:7px}.nitro-track i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#ff4b25,#ffc25c);box-shadow:0 0 10px #ff5a30}.race-message{position:absolute;top:32%;left:50%;transform:translate(-50%,-50%);font:800 36px 'Barlow Condensed',sans-serif;letter-spacing:.18em;color:white;text-shadow:0 2px 15px #000;opacity:0;transition:opacity .2s}.race-message.show{opacity:1}.countdown{position:absolute;z-index:5;left:50%;top:48%;transform:translate(-50%,-50%);font:900 clamp(80px,15vw,160px) 'Barlow Condensed',sans-serif;color:#fff;text-shadow:0 0 35px rgba(255,89,44,.75);pointer-events:none}.touch-controls{display:none;position:absolute;bottom:23px;left:18px;right:18px;justify-content:space-between;align-items:flex-end;pointer-events:none}.touch-controls button{pointer-events:auto;border:1px solid rgba(255,255,255,.42);background:rgba(10,15,19,.4);backdrop-filter:blur(3px);width:62px;height:62px;border-radius:50%;font-size:37px;line-height:1}.touch-right{display:flex;align-items:flex-end;gap:12px}.touch-right button:first-child{width:49px;height:49px;color:#ffb558;font-size:22px}.touch-controls button.pressed{background:rgba(255,84,40,.72)}
@media(max-width:850px){.topbar{height:70px;padding:0 5%}.screen{padding-left:5%;padding-right:5%}.menu-copy{left:8%;top:24%}.vignette{background:linear-gradient(90deg,rgba(5,9,13,.83),rgba(5,9,13,.45) 55%,rgba(5,9,13,.12)),linear-gradient(0deg,rgba(3,6,9,.55),transparent 30%,transparent 75%,rgba(3,6,9,.45))}.location-grid{grid-template-columns:repeat(3,minmax(0,1fr));max-height:calc(100% - 250px)}.selection-heading h2{font-size:57px}.car-groups{gap:10px}.car-card{height:51px;padding:0 7px;gap:7px}.car-card strong{font-size:12px}.car-swatch{width:25px}.heading-note{font-size:9px}}
