ze:8px}.text-button{font-size:8px}.pause-screen,.finish-screen{padding:80px 9% 25px}.pause-screen h2,.finish-screen h2{font-size:84px}.hud-left{top:77px;left:14px;gap:6px}.position-card,.lap-card{padding:7px 8px}.position-card strong{font-size:26px}.position-card span,.position-card small{font-size:7px}.lap-progress{width:65px}.race-title{top:83px}.race-title span{font-size:13px}.race-title small{font-size:6px}.hud-right{top:77px;right:14px;gap:8px}.speed-card strong{font-size:29px}.pause-button{width:31px;height:31px}.nitro-wrap{right:15px;bottom:105px;width:105px}.nitro-wrap small{font-size:6px}.touch-controls{display:flex}.race-message{font-size:29px;top:37%}}
@media(max-height:620px) and (min-width:601px){.menu-copy{top:19%}.selection-screen{padding-top:100px}.location-grid{max-height:calc(100% - 220px)}.car-screen{padding-top:95px}.car-groups{height:calc(100% - 220px)}.car-card{height:45px;margin-bottom:4px}.menu-stats{margin-top:24px}.intro{margin:18px 0}}

'use strict';
(() => {
  const $ = (s) => document.querySelector(s);
  const canvas = $('#game'), ctx = canvas.getContext('2d');
  const locations = [
    ['🇯🇵','Tokyo','Japan','🇯🇵'],['🇬🇧','London','United Kingdom','🇬🇧'],['🇺🇸','Los Angeles','America','🇺🇸'],['🇲🇽','Mexico City','Mexico','🇲🇽'],['🇭🇺','Budapest','Hungary','🇭🇺'],['🇩🇪','Nürburgring','Germany','🇩🇪'],['🇿🇼','Victoria Falls','Zimbabwe','🇿🇼'],['🇳🇬','Lagos','Nigeria','🇳🇬'],['🇫🇷','Paris','France','🇫🇷'],['🇦🇪','Dubai','UAE','🇦🇪'],['🇮🇹','Rome','Italy','🇮🇹'],['🇦🇺','Sydney','Australia','🇦🇺'],['🇧🇷','Rio','Brazil','🇧🇷']
  ].map(([flag,city,country])=>({flag,city,country}));
  const cars = [
    {group:'SUPERCARS',name:'Bugatti Chiron',color:'#f4f2e9',speed:9,handling:7}, {group:'SUPERCARS',name:'Lamborghini Aventador SVJ',color:'#c9df22',speed:9,handling:6},
    {group:'SUPERCARS',name:'Ferrari LaFerrari',color:'#d91f2b',speed:9,handling:8}, {group:'SUPERCARS',name:'McLaren P1',color:'#ff8b16',speed:9,handling:8},
    {group:'SUPERCARS',name:'Koenigsegg Jesko',color:'#c7d6e3',speed:10,handling:7}, {group:'SUPERCARS',name:'Pagani Huayra',color:'#b8b0a1',speed:8,handling:8},
    {group:'SUPERCARS',name:'Ferrari SF90',color:'#e33b26',speed:9,handling:9}, {group:'SUPERCARS',name:'Ford GT',color:'#2884df',speed:8,handling:9},
    {group:'🇯🇵 JAPANESE CARS',name:'Nissan Skyline R34',color:'#4c8ed1',speed:7,handling:9}, {group:'🇯🇵 JAPANESE CARS',name:'Toyota Supra MK4',color:'#e69b35',speed:8,handling:8},
    {group:'🇯🇵 JAPANESE CARS',name:'Mazda RX-7',color:'#bd272c',speed:7,handling:9}, {group:'🇯🇵 JAPANESE CARS',name:'Honda NSX',color:'#f0efea',speed:8,handling:9},
    {group:'🇯🇵 JAPANESE CARS',name:'Nissan Skyline R32',color:'#647380',speed:7,handling:8}, {group:'🇯🇵 JAPANESE CARS',name:'Mitsubishi Evo 9',color:'#e7ecec',speed:7,handling:9},
    {group:'🇯🇵 JAPANESE CARS',name:'Subaru Impreza 22B',color:'#2675cf',speed:7,handling:8},
    {group:'🏁 CLASSIC CARS',name:'Ferrari F40',color:'#c92722',speed:8,handling:7}, {group:'🏁 CLASSIC CARS',name:'Lamborghini Countach',color:'#e5d927',speed:8,handling:6},
    {group:'🏁 CLASSIC CARS',name:'Porsche 911 Carrera RS',color:'#f0e9d8',speed:7,handling:9}, {group:'🏁 CLASSIC CARS',name:'Aston Martin DB5',color:'#9baca1',speed:6,handling:7},
    {group:'🏁 CLASSIC CARS',name:'Ford Escort RS Cosworth',color:'#e7e8e4',speed:7,handling:8}
  ];
  const botNames=['K. Sato','M. Rossi','J. Walker','A. Silva','L. Müller','E. Dubois','D. Okafor','C. Kim','R. Santos','T. Novak'];
  const botColors=['#e9eee8','#e74632','#e8a82c','#3185bd','#a6c837','#9555c8','#f4f2e9','#d35186','#3bb4a2','#df742a'];
  const state={screen:'menu',selectedLocation:0,selectedCar:0,previous:'menu',race:null,sound:true,last:0,width:0,height:0,dpr:1,keys:{},touch:{left:false,right:false,nitro:false},messageTimer:0,seed:1};
  const menu=$('#menu-screen'),locScreen=$('#location-screen'),carScreen=$('#car-screen'),pauseScreen=$('#pause-screen'),finishScreen=$('#finish-screen'),hud=$('#race-hud');
  function showScreen(name){state.screen=name;for(const [key,el] of Object.entries({menu,locations:locScreen,cars:carScreen,paused:pauseScreen,finished:finishScreen}))el.classList.toggle('hidden',key!==name);hud.classList.toggle('hidden',name!=='race');$('#countdown').classList.add('hidden');$('#topbar').style.opacity=name==='race'||name==='paused'||name==='finished'?'0':'1';$('#topbar').style.pointerEvents=name==='race'||name==='paused'||name==='finished'?'none':'auto';}
  function buildMenus(){
    $('#location-grid').innerHTML=locations.map((l,i)=>`<button class="location-card ${i===state.selectedLocation?'selected':''}" data-location="${i}"><span class="flag">${l.flag}</span><strong>${l.city}</strong><small>${l.country.toUpperCase()}</small><span class="card-index">${String(i+1).padStart(2,'0')}</span></button>`).join('');
    $('#location-grid').querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>{state.selectedLocation=+b.dataset.location;buildMenus();$('#selected-location-note').innerHTML=`${locations[state.selectedLocation].city.toUpperCase()}, ${locations[state.selectedLocation].country.toUpperCase()}<br><span>11 racers · 3 laps</span>`;showScreen('cars')});
    const groups=['SUPERCARS','🇯🇵 JAPANESE CARS','🏁 CLASSIC CARS'];
    $('#car-groups').innerHTML=groups.map(group=>`<div class="car-group"><h3 class="group-title">${group}<span>${cars.filter(c=>c.group===group).length} CARS</span></h3>${cars.map((c,i)=>c.group===group?`<button class="car-card ${i===state.selectedCar?'selected':''}" data-car="${i}"><i class="car-swatch" style="background:${c.color}"></i><strong>${c.name}</strong><small>${i===state.selectedCar?'SELECTED':'›'}</small></button>`:'').join('')}</div>`).join('');
    $('#car-groups').querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>{state.selectedCar=+b.dataset.car;buildMenus()});
  }
  buildMenus();
  $('#start-button').onclick=()=>showScreen('locations');
  document.querySelectorAll('.back-button').forEach(b=>b.onclick=()=>showScreen(b.dataset.back));
  $('#home-button').onclick=()=>{if(state.screen==='race'||state.screen==='paused')pauseGame();else showScreen('menu')};
  $('#race-button').onclick=()=>startRace();
  $('#pause-button').onclick=()=>pauseGame();$('#resume-button').onclick=()=>{state.race.paused=false;showScreen('race');state.last=performance.now()};
  $('#restart-button').onclick=()=>startRace();$('#pause-menu-button').onclick=()=>showScreen('menu');
  $('#again-button').onclick=()=>startRace();$('#finish-menu-button').onclick=()=>showScreen('menu');
  $('#next-race-button').onclick=()=>{state.selectedLocation=(state.selectedLocation+1)%locations.length;buildMenus();startRace()};
  $('#sound-button').onclick=()=>{state.sound=!state.sound;$('#sound-button').innerHTML=state.sound?'♫ <span>SOUND ON</span>':'♫ <span>SOUND OFF</span>'};
