'use strict';
(() => {
  const $ = (s) => document.querySelector(s);
  const canvas = $('#game'), ctx = canvas.getContext('2d');
  const locations = [
    ['🇯🇵','Tokyo','Japan'],['🇬🇧','London','United Kingdom'],['🇺🇸','Los Angeles','America'],['🇲🇽','Mexico City','Mexico'],['🇭🇺','Budapest','Hungary'],['🇩🇪','Nürburgring','Germany'],['🇿🇼','Victoria Falls','Zimbabwe'],['🇳🇬','Lagos','Nigeria'],['🇫🇷','Paris','France'],['🇦🇪','Dubai','UAE'],['🇮🇹','Rome','Italy'],['🇦🇺','Sydney','Australia'],['🇧🇷','Rio','Brazil']
  ].map(([flag,city,country])=>({flag,city,country}));
  const cars = [
    ['SUPERCARS','Bugatti Chiron','#f4f2e9',9,7],['SUPERCARS','Lamborghini Aventador SVJ','#c9df22',9,6],['SUPERCARS','Ferrari LaFerrari','#d91f2b',9,8],['SUPERCARS','McLaren P1','#ff8b16',9,8],['SUPERCARS','Koenigsegg Jesko','#c7d6e3',10,7],['SUPERCARS','Pagani Huayra','#b8b0a1',8,8],['SUPERCARS','Ferrari SF90','#e33b26',9,9],['SUPERCARS','Ford GT','#2884df',8,9],
    ['🇯🇵 JAPANESE CARS','Nissan Skyline R34','#4c8ed1',7,9],['🇯🇵 JAPANESE CARS','Toyota Supra MK4','#e69b35',8,8],['🇯🇵 JAPANESE CARS','Mazda RX-7','#bd272c',7,9],['🇯🇵 JAPANESE CARS','Honda NSX','#f0efea',8,9],['🇯🇵 JAPANESE CARS','Nissan Skyline R32','#647380',7,8],['🇯🇵 JAPANESE CARS','Mitsubishi Evo 9','#e7ecec',7,9],['🇯🇵 JAPANESE CARS','Subaru Impreza 22B','#2675cf',7,8],
    ['🏁 CLASSIC CARS','Ferrari F40','#c92722',8,7],['🏁 CLASSIC CARS','Lamborghini Countach','#e5d927',8,6],['🏁 CLASSIC CARS','Porsche 911 Carrera RS','#f0e9d8',7,9],['🏁 CLASSIC CARS','Aston Martin DB5','#9baca1',6,7],['🏁 CLASSIC CARS','Ford Escort RS Cosworth','#e7e8e4',7,8]
  ].map(([group,name,color,speed,handling])=>({group,name,color,speed,handling}));
  const botNames=['K. Sato','M. Rossi','J. Walker','A. Silva','L. Müller','E. Dubois','D. Okafor','C. Kim','R. Santos','T. Novak'];
  const botColors=['#e9eee8','#e74632','#e8a82c','#3185bd','#a6c837','#9555c8','#f4f2e9','#d35186','#3bb4a2','#df742a'];
  const state={screen:'menu',selectedLocation:0,selectedCar:0,race:null,last:0,width:0,height:0,dpr:1,keys:{},touch:{left:false,right:false,nitro:false},messageTimer:0};
  const screens={menu:$('#menu-screen'),locations:$('#location-screen'),cars:$('#car-screen'),paused:$('#pause-screen'),finished:$('#finish-screen')};
  function showScreen(name){state.screen=name;Object.entries(screens).forEach(([key,el])=>el.classList.toggle('hidden',key!==name));$('#race-hud').classList.toggle('hidden',name!=='race');$('#countdown').classList.add('hidden');const inRace=['race','paused','finished'].includes(name);$('#topbar').style.opacity=inRace?'0':'1';$('#topbar').style.pointerEvents=inRace?'none':'auto'}
  function buildMenus(){
    $('#location-grid').innerHTML=locations.map((l,i)=>`<button class="location-card ${i===state.selectedLocation?'selected':''}" data-location="${i}"><span class="flag">${l.flag}</span><strong>${l.city}</strong><small>${l.country.toUpperCase()}</small><span class="card-index">${String(i+1).padStart(2,'0')}</span></button>`).join('');
    $('#location-grid').querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>{state.selectedLocation=+b.dataset.location;buildMenus();const l=locations[state.selectedLocation];$('#selected-location-note').innerHTML=`${l.city.toUpperCase()}, ${l.country.toUpperCase()}<br><span>11 racers · 3 laps</span>`;showScreen('cars')});
    const groups=['SUPERCARS','🇯🇵 JAPANESE CARS','🏁 CLASSIC CARS'];
    $('#car-groups').innerHTML=groups.map(group=>`<div class="car-group"><h3 class="group-title">${group}<span>${cars.filter(c=>c.group===group).length} CARS</span></h3>${cars.map((c,i)=>c.group===group?`<button class="car-card ${i===state.selectedCar?'selected':''}" data-car="${i}"><i class="car-swatch" style="background:${c.color}"></i><strong>${c.name}</strong><small>${i===state.selectedCar?'SELECTED':'›'}</small></button>`:'').join('')}</div>`).join('');
    $('#car-groups').querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>{state.selectedCar=+b.dataset.car;buildMenus()});
  }
  buildMenus();
  $('#start-button').onclick=()=>showScreen('locations');
  document.querySelectorAll('.back-button').forEach(b=>b.onclick=()=>showScreen(b.dataset.back));
  $('#home-button').onclick=()=>{if(state.screen==='race')pauseGame();else showScreen('menu')};
  $('#race-button').onclick=startRace;$('#pause-button').onclick=pauseGame;
  $('#resume-button').onclick=()=>{showScreen('race');state.last=performance.now()};
  $('#restart-button').onclick=startRace;$('#pause-menu-button').onclick=()=>showScreen('menu');
  $('#again-button').onclick=startRace;$('#finish-menu-button').onclick=()=>showScreen('menu');
  $('#next-race-button').onclick=()=>{state.selectedLocation=(state.selectedLocation+1)%locations.length;buildMenus();startRace()};
  $('#sound-button').onclick=()=>{const on=$('#sound-button').textContent.includes('ON');$('#sound-button').innerHTML=on?'♫ <span>SOUND OFF</span>':'♫ <span>SOUND ON</span>'};
  function pauseGame(){if(state.screen==='race')showScreen('paused')}
  function startRace(){const car=cars[state.selectedCar];state.race={playerProgress:0,playerOffset:0,speed:0,nitro:100,boost:0,lapLength:2350,laps:3,elapsed:0,countdown:3,finished:false,car,bots:botNames.map((name,i)=>({name,color:botColors[i],progress:25+i*42,offset:[-.72,.7,-.28,.26,-.86,.88,-.5,.51,-.08,.08][i],speed:82+(i*13%38),phase:i*.8,car:i}))};state.messageTimer=0;showScreen('race');updateHud();$('#countdown').classList.remove('hidden');$('#countdown').textContent='3';state.last=performance.now()}
  const ordinal=n=>n===1?'1ST':n===2?'2ND':n===3?'3RD':`${n}TH`;
  function finishRace(){const r=state.race;if(!r||r.finished)return;r.finished=true;const place=1+r.bots.filter(b=>b.progress>r.playerProgress).length;$('#finish-title').innerHTML=place===1?'YOU<br><span>OWNED IT.</span>':place<=3?'PODIUM<br><span>FINISH.</span>':'RACE<br><span>COMPLETE.</span>';$('#finish-copy').textContent=`${ordinal(place)} place · ${locations[state.selectedLocation].city} · ${r.car.name}`;showScreen('finished')}
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function resize(){const r=canvas.getBoundingClientRect();state.dpr=Math.min(devicePixelRatio||1,2);state.width=r.width;state.height=r.height;canvas.width=Math.round(r.width*state.dpr);canvas.height=Math.round(r.height*state.dpr);ctx.setTransform(state.dpr,0,0,state.dpr,0,0)}
  addEventListener('resize',resize,{passive:true});resize();
  function curve(z,p){return Math.sin(p*.00072+z*2.7)*.10+Math.sin(p*.00031+z*5.2)*.035}
  function roadPoint(z,p){const w=state.width,h=state.height,y=h*.365+Math.pow(z,1.58)*h*.72;return{x:w*.5+curve(z,p)*w,y,width:w*(.045+.455*z)}}
  function drawBackground(now){const w=state.width,h=state.height,idx=state.selectedLocation;const skies=[['#152b3c','#e7a36f','#293935'],['#182b38','#aaa9a1','#303c3d'],['#426e87','#e9ad78','#44634d'],['#506c79','#efb568','#79624a'],['#415468','#efa984','#485144'],['#304456','#efa57b','#424c43'],['#56827a','#f7bd83','#52724f'],['#455f58','#e8a174','#5b674b'],['#30465a','#f1a87e','#3d4c48'],['#3b5d77','#f7b76c','#806447'],['#354b5a','#e9a277','#4e5847'],['#416e8b','#f4bd8a','#476e64'],['#377585','#ffb47f','#377267']][idx];let g=ctx.createLinearGradient(0,0,0,h*.72);g.addColorStop(0,skies[0]);g.addColorStop(.58,skies[1]);g.addColorStop(1,skies[2]);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
    const sx=w*.73,sy=h*.245,sr=Math.min(w,h)*.07;g=ctx.createRadialGradient(sx,sy,2,sx,sy,sr*2.5);g.addColorStop(0,'rgba(255,235,194,.7)');g.addColorStop(.3,'rgba(255,195,135,.23)');g.addColorStop(1,'rgba(255,175,125,0)');ctx.fillStyle=g;ctx.fillRect(sx-sr*3,sy-sr*3,sr*6,sr*6);ctx.fillStyle='rgba(255,225,182,.76)';ctx.beginPath();ctx.arc(sx,sy,sr*.5,0,Math.PI*2);ctx.fill();
    const hy=h*.365;ctx.fillStyle=idx===3||idx===9?'#806b56':'#34433d';ctx.beginPath();ctx.moveTo(0,hy+20);for(let x=0;x<=w+40;x+=35)ctx.lineTo(x,hy+Math.sin(x*.009)*9+Math.sin(x*.021)*5+8);ctx.lineTo(w,hy+80);ctx.lineTo(0,hy+80);ctx.fill();
